package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SimilarShapeSupplyTest {
 @Test public void allConditionsAndPublicBlankHelp(){Set<String> seen=new HashSet<>();for(int i=0;i<1078;i++){Question q=SimilarShapeSupply.at(i);assertTrue(seen.add(q.signature()));int a=(i/2)%49+2,k=(i/2)/49+2;String answer=""+(i%2==0?a*k:k);assertTrue(new Checker().check(q,List.of(),List.of(answer)).correct());assertEquals("similarShapePair",q.diagram.type);assertArrayEquals(new double[]{i%2,a,i%2==0?k:a*k},q.diagram.values,0);q.expression="poison";q.answers=new String[]{"999"};HelpPlan h=HelpPlan.forQuestion(q);assertEquals(3,h.size());assertFalse(h.canTransfer());List<String> entries=i%2==0?List.of(""+k,""+a,""+(a*k)):List.of(""+a,""+(a*k),""+k);for(int j=0;j<3;j++){assertTrue(h.step(j).accepts(entries.get(j)));assertFalse(h.step(j).accepts("999"));assertFalse(h.step(j).before.contains(entries.get(2)+" = "));}}}
 @Test public void yearSixSupplyFreshAndBothDirections(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(SimilarShapeSupply.ID,6));List<String> recent=new ArrayList<>();Set<Boolean> modes=new HashSet<>();Generator g=new Generator(new Random(100));for(int i=0;i<150;i++){Question q=g.next(SimilarShapeSupply.ID,recent,false,GlobalCurriculum.limits(pack.id,SimilarShapeSupply.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());modes.add(SimilarShapeSupply.read(q)!=null);}assertEquals(2,modes.size());}
 @Test public void ordinarySupplyAndExistingVersionPreserved(){Question q=new Generator(new Random(2)).create(Catalog.get(SimilarShapeSupply.ID));assertNull(q.diagram);assertEquals("similarity-measure-relations-v1",q.studyGuide.teachingVersion);assertEquals(3,HelpPlan.forQuestion(q).size());}
}
